head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf75100";
scwin.fn_searchIntegSrch = null;
scwin.fn_searchKeywrdMapping = null;
scwin.fn_searchKeywrdListDtl = null;
scwin.fn_removeKeywrd = null;
scwin.fn_regKeywrd = null;
scwin.fn_chkKeywrd = null;
scwin.fn_moveIntegsrch = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — usrLdMktTpCd, pageContext.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.fn_searchIntegSrch = scwin.tx_fn_searchIntegSrch;
        scwin.fn_searchKeywrdMapping = scwin.tx_fn_searchKeywrdMapping;
        scwin.fn_searchKeywrdListDtl = scwin.tx_fn_searchKeywrdListDtl;
        scwin.fn_removeKeywrd = scwin.tx_fn_removeKeywrd;
        scwin.fn_regKeywrd = scwin.tx_fn_regKeywrd;
        scwin.fn_chkKeywrd = scwin.tx_fn_chkKeywrd;
        scwin.fn_moveIntegsrch = scwin.tx_fn_moveIntegsrch;
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf75100.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '2'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '6'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_formatKeywrd", fn: function () { return String(String((dma_pageContext.get("formatKeywrd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        setCommonSelect("ldMktTpCd");
        scwin.fn_searchKeywrdListDtl();
        scwin.fn_searchIntegSrch();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75100.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
