 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_14_onclick = function(e){
    try {
        openKeywrdList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75100.input_14_onclick' }); }
};

