/**
 * @method
 * @name grd_keywrdMappList_oncellclick
 * @description grd_keywrdMappList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_keywrdMappList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_keywrdMappList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_keywrdMappList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        /* TODO Stage2: 행 동작 미정의: scwin.fn_removeKeywrd (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fn_removeKeywrd'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_keywrdMappList.oncellclick' });
    }
};

