 * @description on enter 1 ipt formatkeywrd 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.__on_enter_1_ipt_formatkeywrd = function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ scwin.fn_searchIntegSrch() }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf75100.__on_enter_1_ipt_formatKeywrd' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchIntegSrch
 * @description search Integ Srch 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchIntegSrch = async function () {
    const sbmOptions = {
        id: "tx_fn_searchIntegSrch",
        method: "post",
        action: "/ods/integsrchBy.do",
        ref: "dma_searchIntegSrchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

