    const sbmOptions = {
        id: "tx_fn_chkKeywrd",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_chkKeywrdReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_moveIntegsrch
 * @description move Integsrch 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_moveIntegsrch = async function () {
    const sbmOptions = {
        id: "tx_fn_moveIntegsrch",
        method: "post",
        action: "/ods/integsrchBy.do",
        ref: "dma_moveIntegsrchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchKey
 * @description search Key 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchKey = function () {
    if (event.keyCode === 13) {
        scwin.fn_searchKeywrdListDtl();
        $('.sort a').removeClass('active');
        (($c.util.getComponent('all')) && ($c.util.getComponent('all')).addClass ? ($c.util.getComponent('all')).addClass('active') : console.error('[sdd] addClass 미지원 컴포넌트: all'));
    }
};

/**
 * @method
 * @name moveKeywrdList
 * @description move Keywrd List 처리
 * @returns {void}
 * @hidden N
 */
scwin.moveKeywrdList = function () {
    scwin.fn_searchKeywrdListDtl("", true);
};

/**
 * @method
 * @name setKeywrd
 * @description set Keywrd 처리
 * @param {*} keywrd keywrd
 * @returns {void}
 * @hidden N
 */
scwin.setKeywrd = function (keywrd) {
    $c.util.getComponent('ipt_formatKeywrd').setValue(keywrd);
};

/**
 * @method
 * @name clickKeyword
 * @description click Keyword 처리
 * @param {*} ele ele
 * @returns {void}
 * @hidden N
 */
scwin.clickKeyword = function (ele) {
    $('.sort a').on('click', function() {
            if ($(this).hasClass('active')) {
                return false;
            }
            $('.sort a').removeClass('active');
            $(this).addClass('active');
    });
};
